package main

type Clause struct {
	Head, Body *Term
	File       string
	Line       int
}
type Predicate struct {
	Indicator Indicator
	Clauses   []*Clause
}
type Database struct {
	Predicates map[Indicator]*Predicate
	Order      []*Predicate
}

func newDatabase() *Database { return &Database{Predicates: map[Indicator]*Predicate{}} }
func (d *Database) ensure(p Indicator) *Predicate {
	if previous := d.Predicates[p]; previous != nil {
		return previous
	}
	predicate := &Predicate{Indicator: p}
	d.Predicates[p] = predicate
	d.Order = append(d.Order, predicate)
	return predicate
}
func sameKind(a, b *Term) bool {
	a, b = dereference(a), dereference(b)
	if a.Kind == "variable" || b.Kind == "variable" {
		return true
	}
	if a.Kind != b.Kind {
		return false
	}
	switch a.Kind {
	case "integer":
		return a.Integer == b.Integer
	case "atom":
		return a.Name == b.Name
	case "compound":
		return a.Name == b.Name && len(a.Arguments) == len(b.Arguments)
	}
	return false
}
func (p *Predicate) candidates(goal *Term) []*Clause {
	out := []*Clause{}
	for _, clause := range p.Clauses {
		if p.Indicator.Arity == 0 || sameKind(goal.Arguments[0], clause.Head.Arguments[0]) {
			out = append(out, clause)
		}
	}
	return out
}
func copyClause(c *Clause) (*Term, *Term) {
	copier := newCopier()
	head := copier.copy(c.Head)
	var body *Term
	if c.Body != nil {
		body = copier.copy(c.Body)
	}
	return head, body
}

package main

import (
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

type Writer struct {
	Quoted bool
	Names  map[*Term]string
	Serial int
}

func newWriter(quoted bool) *Writer { return &Writer{Quoted: quoted, Names: map[*Term]string{}} }
func operatorName(name string) bool {
	_, infix := infixOperators[name]
	_, prefix := prefixOperators[name]
	return infix || prefix
}
func (w *Writer) atomName(name string) string {
	if !w.Quoted {
		return name
	}
	plain := name == "[]" || name == "!" || name == ";"
	if len(name) > 0 {
		if lower(name[0]) {
			plain = true
			for i := 0; i < len(name); i++ {
				plain = plain && alphanumeric(name[i])
			}
		}
		allSymbols := true
		for i := 0; i < len(name); i++ {
			allSymbols = allSymbols && symbol(name[i])
		}
		plain = plain || allSymbols && name != "."
	}
	if plain {
		return name
	}
	var out strings.Builder
	out.WriteByte('\'')
	for i := 0; i < len(name); i++ {
		switch name[i] {
		case '\\':
			out.WriteString("\\\\")
		case '\'':
			out.WriteString("\\'")
		case '\n':
			out.WriteString("\\n")
		case '\t':
			out.WriteString("\\t")
		default:
			out.WriteByte(name[i])
		}
	}
	out.WriteByte('\'')
	return out.String()
}
func (w *Writer) write(t *Term, limit int, operand bool) string {
	t = dereference(t)
	switch t.Kind {
	case "variable":
		if name, exists := w.Names[t]; exists {
			return name
		}
		w.Serial++
		name := fmt.Sprintf("_G%d", w.Serial)
		w.Names[t] = name
		return name
	case "integer":
		return strconv.FormatInt(t.Integer, 10)
	case "atom":
		name := w.atomName(t.Name)
		if operand && operatorName(t.Name) {
			return "(" + name + ")"
		}
		return name
	}
	if isCompound(t, ".", 2) {
		elements, tail := listParts(t)
		parts := []string{}
		for _, element := range elements {
			parts = append(parts, w.write(element, 999, false))
		}
		value := "[" + strings.Join(parts, ",")
		if !isNil(tail) {
			value += "|" + w.write(tail, 999, false)
		}
		return value + "]"
	}
	if op, ok := infixOperators[t.Name]; ok && len(t.Arguments) == 2 {
		left := w.write(t.Arguments[0], op.Left, true)
		right := w.write(t.Arguments[1], op.Right, true)
		value := ""
		if t.Name == "," {
			value = left + "," + right
		} else if lower(t.Name[0]) {
			value = left + " " + t.Name + " " + right
		} else {
			before, after := "", ""
			if len(left) > 0 && symbol(left[len(left)-1]) {
				before = " "
			}
			if len(right) > 0 && symbol(right[0]) {
				after = " "
			}
			value = left + before + t.Name + after + right
		}
		if op.Priority > limit {
			value = "(" + value + ")"
		}
		return value
	}
	if priority, ok := prefixOperators[t.Name]; ok && len(t.Arguments) == 1 {
		arg := w.write(t.Arguments[0], priority, true)
		gap := ""
		if len(arg) > 0 && (symbol(arg[0]) || digit(arg[0]) || arg[0] == '(') {
			gap = " "
		}
		value := t.Name + gap + arg
		if priority > limit {
			value = "(" + value + ")"
		}
		return value
	}
	parts := []string{}
	for _, arg := range t.Arguments {
		parts = append(parts, w.write(arg, 999, false))
	}
	return w.atomName(t.Name) + "(" + strings.Join(parts, ",") + ")"
}
func termText(t *Term) string          { return newWriter(true).write(t, 1200, false) }
func indicatorText(p Indicator) string { return termText(indicatorTerm(p)) }
func control(p Indicator) bool {
	return p == (Indicator{",", 2}) || p == (Indicator{"!", 0}) || p == (Indicator{";", 2}) || p == (Indicator{"->", 2}) || p == (Indicator{"\\+", 1}) || p == (Indicator{"catch", 3}) || p.Name == "call" && p.Arity >= 1 && p.Arity <= 8
}
func builtin(p Indicator) bool {
	return deterministicIndicators[p] || p == (Indicator{"findall", 3}) || p == (Indicator{"throw", 1}) || p == (Indicator{"between", 3}) || p == (Indicator{"length", 2})
}
func goalConversion(t *Term) (*Term, bool) {
	t = dereference(t)
	if t.Kind == "variable" {
		return compound("call", t), true
	}
	if t.Kind == "integer" {
		return nil, false
	}
	if t.Kind == "compound" && len(t.Arguments) == 2 && (t.Name == "," || t.Name == ";" || t.Name == "->") {
		a, ok := goalConversion(t.Arguments[0])
		if !ok {
			return nil, false
		}
		b, ok := goalConversion(t.Arguments[1])
		if !ok {
			return nil, false
		}
		return compound(t.Name, a, b), true
	}
	return t, true
}

type ConsultStats struct{ Clauses, Errors, Warnings int }
type Consultant struct {
	Database   *Database
	Reports    []string
	Statistics map[string]*ConsultStats
}

func newConsultant() *Consultant {
	return &Consultant{Database: newDatabase(), Statistics: map[string]*ConsultStats{"prelude.pl": {}, "program.pl": {}}}
}
func (c *Consultant) warning(file string, line int, message string) {
	c.Reports = append(c.Reports, fmt.Sprintf("%s:%d: warning: %s", file, line, message))
	c.Statistics[file].Warnings++
}
func (c *Consultant) consult(file, source string) {
	reader := &Reader{Tokens: lex(source, 1)}
	lines := strings.Split(strings.TrimSuffix(source, "\n"), "\n")
	seen := map[Indicator]bool{}
	warned := map[Indicator]bool{}
	var last Indicator
	hasLast := false
	for reader.peek().Kind != "eof" {
		line := reader.peek().Position.Line
		term, issue := readClause(reader, false)
		if issue != nil {
			token := issue.Token
			c.Reports = append(c.Reports, fmt.Sprintf("%s:%d:%d: syntax error: %s", file, token.Position.Line, token.Position.Column, issue.Message))
			if token.Kind != "eof" {
				c.Reports = append(c.Reports, "    "+lines[token.Position.Line-1], strings.Repeat(" ", token.Position.Column+3)+"^")
			}
			c.Statistics[file].Errors++
			reader.Index = issue.Index
			for reader.peek().Kind != "end" && reader.peek().Kind != "eof" {
				reader.take()
			}
			if reader.peek().Kind == "end" {
				reader.take()
			}
			continue
		}
		head := term
		var body *Term
		if isCompound(term, ":-", 2) {
			head = term.Arguments[0]
			body = term.Arguments[1]
		}
		var error *Term
		if head.Kind == "variable" {
			error = atom("instantiation_error")
		} else if head.Kind == "integer" {
			error = errorTerm("type_error", atom("callable"), head)
		} else {
			p := indicator(head)
			if control(p) || builtin(p) {
				error = errorTerm("permission_error", atom("modify"), atom("static_procedure"), indicatorTerm(p))
			} else if body != nil {
				converted, ok := goalConversion(body)
				if !ok {
					error = errorTerm("type_error", atom("callable"), body)
				} else {
					body = converted
				}
			}
		}
		if error != nil {
			c.Reports = append(c.Reports, fmt.Sprintf("%s:%d: error: %s", file, line, termText(error)))
			c.Statistics[file].Errors++
			continue
		}
		p := indicator(head)
		predicate := c.Database.ensure(p)
		if file == "program.pl" && len(predicate.Clauses) > 0 && predicate.Clauses[0].File == "prelude.pl" {
			c.warning(file, line, "redefining prelude procedure "+indicatorText(p))
			predicate.Clauses = nil
		}
		if seen[p] && hasLast && last != p && !warned[p] {
			c.warning(file, line, "clauses of "+indicatorText(p)+" are not together")
			warned[p] = true
		}
		predicate.Clauses = append(predicate.Clauses, &Clause{Head: head, Body: body, File: file, Line: line})
		seen[p] = true
		last = p
		hasLast = true
		c.Statistics[file].Clauses++
		singles, repeated := []string{}, []string{}
		for _, name := range reader.Order {
			if !strings.HasPrefix(name, "_") && reader.Counts[name] == 1 {
				singles = append(singles, name)
			}
			if len(name) >= 2 && name[0] == '_' && reader.Counts[name] >= 2 {
				repeated = append(repeated, name)
			}
		}
		if len(singles) > 0 {
			c.warning(file, line, "singleton variables: "+strings.Join(singles, ", "))
		}
		if len(repeated) > 0 {
			c.warning(file, line, "variables starting with _ occur more than once: "+strings.Join(repeated, ", "))
		}
	}
}
func (c *Consultant) undefinedWarnings() {
	reported := map[Indicator]bool{}
	for _, predicate := range c.Database.Order {
		for _, clause := range predicate.Clauses {
			if clause.Body == nil {
				continue
			}
			var walk func(*Term)
			walk = func(t *Term) {
				t = dereference(t)
				if t.Kind == "variable" || t.Kind == "integer" {
					return
				}
				p := indicator(t)
				switch {
				case p.Arity == 2 && (p.Name == "," || p.Name == ";" || p.Name == "->"):
					walk(t.Arguments[0])
					walk(t.Arguments[1])
				case p == (Indicator{"\\+", 1}) || p == (Indicator{"call", 1}):
					walk(t.Arguments[0])
				case p == (Indicator{"findall", 3}):
					walk(t.Arguments[1])
				case p == (Indicator{"catch", 3}):
					walk(t.Arguments[0])
					walk(t.Arguments[2])
				default:
					if !control(p) && !builtin(p) && c.Database.Predicates[p] == nil && !reported[p] {
						reported[p] = true
						c.warning(clause.File, clause.Line, "undefined procedure "+indicatorText(p)+" called from "+indicatorText(predicate.Indicator))
					}
				}
			}
			walk(clause.Body)
		}
	}
}
func (c *Consultant) reportLines() []string {
	out := append([]string{}, c.Reports...)
	for _, file := range []string{"prelude.pl", "program.pl"} {
		s := c.Statistics[file]
		out = append(out, fmt.Sprintf("%s: clauses=%d errors=%d warnings=%d", file, s.Clauses, s.Errors, s.Warnings))
	}
	clauses := 0
	for _, p := range c.Database.Order {
		clauses += len(p.Clauses)
	}
	return append(out, fmt.Sprintf("database: predicates=%d clauses=%d", len(c.Database.Order), clauses))
}
func listing(database *Database) []string {
	out := []string{}
	for i, p := range database.Order {
		if i > 0 {
			out = append(out, "")
		}
		for _, clause := range p.Clauses {
			counts := map[*Term]int{}
			order := []*Term{}
			values := termVariables(clause.Head)
			if clause.Body != nil {
				values = append(values, termVariables(clause.Body)...)
			}
			for _, v := range values {
				if counts[v] == 0 {
					order = append(order, v)
				}
				counts[v]++
			}
			writer := newWriter(true)
			serial := 0
			for _, v := range order {
				if counts[v] == 1 {
					writer.Names[v] = "_"
				} else {
					name := string(byte('A' + serial%26))
					if serial >= 26 {
						name += strconv.Itoa(serial / 26)
					}
					writer.Names[v] = name
					serial++
				}
			}
			head := writer.write(clause.Head, 1200, false)
			if clause.Body == nil {
				out = append(out, head+".")
				continue
			}
			out = append(out, head+" :-")
			goals := []*Term{}
			body := clause.Body
			for isCompound(body, ",", 2) {
				goals = append(goals, body.Arguments[0])
				body = body.Arguments[1]
			}
			goals = append(goals, body)
			for j, goal := range goals {
				end := ","
				if j == len(goals)-1 {
					end = "."
				}
				out = append(out, "    "+writer.write(goal, 999, false)+end)
			}
		}
	}
	return out
}

type QueryVariable struct {
	Name string
	Term *Term
}

func answer(variables []QueryVariable) string {
	writer := newWriter(true)
	for _, v := range variables {
		value := dereference(v.Term)
		if value.Kind == "variable" {
			if _, exists := writer.Names[value]; !exists {
				writer.Names[value] = v.Name
			}
		}
	}
	last := map[*Term]string{}
	items := []string{}
	for _, v := range variables {
		value := dereference(v.Term)
		if value.Kind == "variable" {
			if previous, exists := last[value]; exists {
				items = append(items, previous+" = "+v.Name)
			}
			last[value] = v.Name
		} else {
			items = append(items, v.Name+" = "+writer.write(value, 699, true))
		}
	}
	if len(items) == 0 {
		return "true"
	}
	return strings.Join(items, ", ")
}

type GoalEntry struct {
	Goal            *Term
	Marker          string
	Height, Barrier int
	Frame, Context  *Choice
}
type GoalNode struct {
	Entry GoalEntry
	Next  *GoalNode
}

func prepend(entries []GoalEntry, tail *GoalNode) *GoalNode {
	for i := len(entries) - 1; i >= 0; i-- {
		tail = &GoalNode{Entry: entries[i], Next: tail}
	}
	return tail
}

type Choice struct {
	Kind                   string
	Mark                   int
	Resume                 *GoalNode
	Goal                   *Term
	Clauses                []*Clause
	NextClause, Barrier    int
	Context                *Choice
	High, NextValue, Base  int64
	Variable, Tail, Length *Term
	Catcher, Recovery      *Term
	Parent                 *Choice
	Template, Result       *Term
	Results                []*Term
}
type Profile struct{ Calls, Tries int }
type Ball struct{ Term *Term }
type Machine struct {
	Database                                   *Database
	Profiles                                   map[Indicator]*Profile
	Bindings                                   Bindings
	Goals                                      *GoalNode
	Choices                                    []*Choice
	Variables                                  []QueryVariable
	Limit                                      int
	Inferences, Created, Backtracks, Solutions int
	End                                        string
	Exception                                  *Term
	Answers                                    []string
	Output                                     strings.Builder
}

func (m *Machine) profile(p Indicator) *Profile {
	profile := m.Profiles[p]
	if profile == nil {
		profile = &Profile{}
		m.Profiles[p] = profile
	}
	return profile
}
func (m *Machine) push(choice *Choice) {
	choice.Mark = m.Bindings.mark()
	m.Choices = append(m.Choices, choice)
	m.Created++
}
func (m *Machine) cut(height int) { m.Choices = m.Choices[:height] }
func (m *Machine) inference(p Indicator) bool {
	if m.Inferences == 20000 {
		m.End = "limit"
		return false
	}
	m.Inferences++
	m.profile(p).Calls++
	return true
}
func goalEntry(goal *Term, barrier int, context *Choice) GoalEntry {
	return GoalEntry{Goal: goal, Barrier: barrier, Context: context}
}
func (m *Machine) tryClause(goal *Term, clause *Clause, barrier int, context *Choice, continuation *GoalNode) bool {
	m.profile(indicator(goal)).Tries++
	head, body := copyClause(clause)
	if !m.Bindings.unify(head, goal) {
		return false
	}
	m.Goals = continuation
	if body != nil {
		m.Goals = prepend([]GoalEntry{goalEntry(body, barrier, context)}, continuation)
	}
	return true
}
func (m *Machine) step(entry GoalEntry, continuation *GoalNode) (success bool, ball *Term) {
	defer func() {
		if failure := recover(); failure != nil {
			switch issue := failure.(type) {
			case Ball:
				ball = issue.Term
			case BuiltinIssue:
				ball = errorBall(issue.Term, indicator(dereference(entry.Goal)))
			default:
				panic(failure)
			}
		}
	}()
	c, k := entry.Barrier, entry.Context
	m.Goals = continuation
	if entry.Marker != "" {
		switch entry.Marker {
		case "ITE":
			m.cut(entry.Height)
			return true, nil
		case "NAF":
			m.cut(entry.Height)
			return false, nil
		case "EXIT":
			if len(m.Choices) > 0 && m.Choices[len(m.Choices)-1] == entry.Frame {
				m.Choices = m.Choices[:len(m.Choices)-1]
			}
			return true, nil
		case "COLLECT":
			entry.Frame.Results = append(entry.Frame.Results, copyTerm(entry.Frame.Template))
			return false, nil
		}
	}
	goal := dereference(entry.Goal)
	p := indicator(goal)
	args := goal.Arguments
	if control(p) {
		switch p.Name {
		case ",":
			m.Goals = prepend([]GoalEntry{goalEntry(args[0], c, k), goalEntry(args[1], c, k)}, continuation)
		case "!":
			m.cut(c)
		case ";":
			h := len(m.Choices)
			m.push(&Choice{Kind: "ALT", Resume: prepend([]GoalEntry{goalEntry(args[1], c, k)}, continuation)})
			if left := dereference(args[0]); isCompound(left, "->", 2) {
				m.Goals = prepend([]GoalEntry{goalEntry(left.Arguments[0], h+1, k), {Marker: "ITE", Height: h, Barrier: c, Context: k}, goalEntry(left.Arguments[1], c, k)}, continuation)
			} else {
				m.Goals = prepend([]GoalEntry{goalEntry(args[0], c, k)}, continuation)
			}
		case "->":
			h := len(m.Choices)
			m.Goals = prepend([]GoalEntry{goalEntry(args[0], h, k), {Marker: "ITE", Height: h, Barrier: c, Context: k}, goalEntry(args[1], c, k)}, continuation)
		case "\\+":
			h := len(m.Choices)
			m.push(&Choice{Kind: "ALT", Resume: continuation})
			m.Goals = prepend([]GoalEntry{goalEntry(compound("call", args[0]), c, k), {Marker: "NAF", Height: h, Barrier: c, Context: k}}, continuation)
		case "call":
			target := dereference(args[0])
			if target.Kind == "variable" {
				panic(Ball{errorBall(atom("instantiation_error"), p)})
			}
			if target.Kind == "integer" {
				panic(Ball{errorBall(errorTerm("type_error", atom("callable"), target), p)})
			}
			if len(args) > 1 {
				values := []*Term{}
				if target.Kind == "compound" {
					values = append(values, target.Arguments...)
				}
				values = append(values, args[1:]...)
				target = compound(target.Name, values...)
			}
			converted, ok := goalConversion(target)
			if !ok {
				panic(Ball{errorBall(errorTerm("type_error", atom("callable"), target), p)})
			}
			m.Goals = prepend([]GoalEntry{goalEntry(converted, len(m.Choices), k)}, continuation)
		case "catch":
			frame := &Choice{Kind: "CATCH", Resume: continuation, Catcher: args[1], Recovery: args[2], Parent: k}
			m.push(frame)
			m.Goals = prepend([]GoalEntry{goalEntry(compound("call", args[0]), c, frame), {Marker: "EXIT", Frame: frame, Barrier: c, Context: k}}, continuation)
		}
		return true, nil
	}
	if !m.inference(p) {
		return false, nil
	}
	switch p {
	case Indicator{"findall", 3}:
		frame := &Choice{Kind: "FINDALL", Resume: continuation, Template: args[0], Result: args[2]}
		m.push(frame)
		m.Goals = prepend([]GoalEntry{goalEntry(compound("call", args[1]), c, k), {Marker: "COLLECT", Frame: frame, Barrier: c, Context: k}}, nil)
		return true, nil
	case Indicator{"throw", 1}:
		value := dereference(args[0])
		if value.Kind == "variable" {
			panic(Ball{errorBall(atom("instantiation_error"), p)})
		}
		panic(Ball{value})
	case Indicator{"between", 3}:
		low := integerCheck(args[0])
		high := integerCheck(args[1])
		value := dereference(args[2])
		if value.Kind != "variable" && value.Kind != "integer" {
			predicateError(errorTerm("type_error", atom("integer"), value))
		}
		if value.Kind == "integer" {
			return value.Integer >= low && value.Integer <= high, nil
		}
		if low > high {
			return false, nil
		}
		if low < high {
			m.push(&Choice{Kind: "BETWEEN", Resume: continuation, High: high, NextValue: low + 1, Variable: args[2]})
		}
		return m.Bindings.unify(args[2], integer(low)), nil
	case Indicator{"length", 2}:
		length := dereference(args[1])
		if length.Kind != "variable" && length.Kind != "integer" {
			predicateError(errorTerm("type_error", atom("integer"), length))
		}
		if length.Kind == "integer" && length.Integer < 0 {
			predicateError(errorTerm("domain_error", atom("not_less_than_zero"), length))
		}
		elements, tail := listParts(args[0])
		base := int64(len(elements))
		if isNil(tail) {
			return m.Bindings.unify(args[1], integer(base)), nil
		}
		if tail.Kind != "variable" {
			predicateError(errorTerm("type_error", atom("list"), args[0]))
		}
		if length.Kind == "integer" {
			if length.Integer < base {
				return false, nil
			}
			values := []*Term{}
			for i := base; i < length.Integer; i++ {
				values = append(values, variable())
			}
			return m.Bindings.unify(tail, makeList(values, nil)), nil
		}
		m.push(&Choice{Kind: "LENGTH", Resume: continuation, Tail: tail, Length: args[1], Base: base, NextValue: base + 1})
		return m.Bindings.unify(tail, atom("[]")) && m.Bindings.unify(args[1], integer(base)), nil
	}
	if deterministicIndicators[p] {
		return deterministic(goal, &m.Bindings, &m.Output), nil
	}
	predicate := m.Database.Predicates[p]
	if predicate == nil {
		panic(Ball{errorBall(errorTerm("existence_error", atom("procedure"), indicatorTerm(p)), p)})
	}
	candidates := predicate.candidates(goal)
	if len(candidates) == 0 {
		return false, nil
	}
	height := len(m.Choices)
	if len(candidates) > 1 {
		m.push(&Choice{Kind: "CLAUSES", Resume: continuation, Goal: goal, Clauses: candidates, NextClause: 1, Barrier: height, Context: k})
	}
	return m.tryClause(goal, candidates[0], height, k, continuation), nil
}
func (m *Machine) backtrack() bool {
	increment := true
	for {
		if increment {
			m.Backtracks++
		}
		increment = true
		if len(m.Choices) == 0 {
			m.End = "exhausted"
			return false
		}
		choice := m.Choices[len(m.Choices)-1]
		m.Bindings.undo(choice.Mark)
		switch choice.Kind {
		case "ALT":
			m.Choices = m.Choices[:len(m.Choices)-1]
			m.Goals = choice.Resume
			return true
		case "CLAUSES":
			index := choice.NextClause
			if index == len(choice.Clauses)-1 {
				m.Choices = m.Choices[:len(m.Choices)-1]
			} else {
				choice.NextClause++
			}
			if m.tryClause(choice.Goal, choice.Clauses[index], choice.Barrier, choice.Context, choice.Resume) {
				return true
			}
		case "BETWEEN":
			if !m.inference(Indicator{"between", 3}) {
				return false
			}
			value := choice.NextValue
			if value == choice.High {
				m.Choices = m.Choices[:len(m.Choices)-1]
			} else {
				choice.NextValue++
			}
			if m.Bindings.unify(choice.Variable, integer(value)) {
				m.Goals = choice.Resume
				return true
			}
		case "LENGTH":
			if !m.inference(Indicator{"length", 2}) {
				return false
			}
			length := choice.NextValue
			choice.NextValue++
			values := []*Term{}
			for i := choice.Base; i < length; i++ {
				values = append(values, variable())
			}
			if m.Bindings.unify(choice.Tail, makeList(values, nil)) && m.Bindings.unify(choice.Length, integer(length)) {
				m.Goals = choice.Resume
				return true
			}
		case "CATCH":
			m.Choices = m.Choices[:len(m.Choices)-1]
			increment = false
		case "FINDALL":
			m.Choices = m.Choices[:len(m.Choices)-1]
			if m.Bindings.unify(makeList(choice.Results, nil), choice.Result) {
				m.Goals = choice.Resume
				return true
			}
		}
	}
}
func (m *Machine) exception(ball *Term, context *Choice) bool {
	ball = copyTerm(ball)
	for context != nil {
		index := len(m.Choices) - 1
		for m.Choices[index] != context {
			index--
		}
		m.Choices = m.Choices[:index]
		m.Bindings.undo(context.Mark)
		mark := m.Bindings.mark()
		if m.Bindings.unify(copyTerm(ball), context.Catcher) {
			m.Goals = prepend([]GoalEntry{goalEntry(compound("call", context.Recovery), len(m.Choices), context.Parent)}, context.Resume)
			return true
		}
		m.Bindings.undo(mark)
		context = context.Parent
	}
	m.Exception = ball
	m.End = "exception"
	return false
}
func (m *Machine) run(query *Term) {
	m.Goals = prepend([]GoalEntry{goalEntry(compound("call", query), 0, nil)}, nil)
	for m.End == "" {
		if m.Goals == nil {
			m.Solutions++
			value := answer(m.Variables)
			if m.Limit > 0 && m.Solutions == m.Limit || len(m.Choices) == 0 {
				m.Answers = append(m.Answers, value+".")
				m.End = "done"
				break
			}
			m.Answers = append(m.Answers, value+" ;")
			if !m.backtrack() {
				break
			}
			continue
		}
		entry := m.Goals.Entry
		continuation := m.Goals.Next
		success, ball := m.step(entry, continuation)
		if m.End != "" {
			break
		}
		if ball != nil {
			if !m.exception(ball, entry.Context) {
				break
			}
		} else if !success {
			if !m.backtrack() {
				break
			}
		}
	}
	switch m.End {
	case "exhausted":
		m.Answers = append(m.Answers, "false.")
	case "exception":
		m.Answers = append(m.Answers, "uncaught exception: "+termText(m.Exception))
	case "limit":
		m.Answers = append(m.Answers, "inference limit exceeded")
	}
}
func readText(path string) string {
	data, err := os.ReadFile(path)
	if err != nil {
		panic(err)
	}
	return string(data)
}
func save(name string, lines []string) {
	text := ""
	if len(lines) > 0 {
		text = strings.Join(lines, "\n") + "\n"
	}
	if err := os.WriteFile("output/"+name, []byte(text), 0644); err != nil {
		panic(err)
	}
}
func main() {
	consultant := newConsultant()
	for _, file := range []string{"prelude.pl", "program.pl"} {
		consultant.consult(file, readText("input/"+file))
	}
	consultant.undefinedWarnings()
	profiles := map[Indicator]*Profile{}
	answers, stats := []string{}, []string{}
	var writes strings.Builder
	totals := [4]int{}
	querySource := readText("input/queries.txt")
	lines := []string{}
	if querySource != "" {
		lines = strings.Split(strings.TrimSuffix(querySource, "\n"), "\n")
	}
	for i, line := range lines {
		number := i + 1
		answers = append(answers, line)
		fmt.Fprintf(&writes, "== query %d ==\n", number)
		marker := strings.Index(line, "?- ")
		bodyStart := marker + 3
		limit := 0
		if marker > 0 {
			value, err := strconv.Atoi(strings.TrimSpace(line[:marker]))
			if err != nil {
				panic(err)
			}
			limit = value
		}
		reader := &Reader{Tokens: lex(line[bodyStart:], bodyStart+1)}
		query, issue := readClause(reader, true)
		if issue != nil {
			answers = append(answers, fmt.Sprintf("syntax error at column %d: %s", issue.Token.Position.Column, issue.Message))
			stats = append(stats, fmt.Sprintf("query %d: syntax error", number))
			continue
		}
		variables := []QueryVariable{}
		for _, name := range reader.Order {
			if !strings.HasPrefix(name, "_") {
				variables = append(variables, QueryVariable{name, reader.Named[name]})
			}
		}
		machine := &Machine{Database: consultant.Database, Profiles: profiles, Variables: variables, Limit: limit}
		machine.run(query)
		answers = append(answers, machine.Answers...)
		text := machine.Output.String()
		writes.WriteString(text)
		if text != "" && !strings.HasSuffix(text, "\n") {
			writes.WriteByte('\n')
		}
		stats = append(stats, fmt.Sprintf("query %d: solutions=%d inferences=%d choicepoints=%d backtracks=%d", number, machine.Solutions, machine.Inferences, machine.Created, machine.Backtracks))
		totals[0] += machine.Solutions
		totals[1] += machine.Inferences
		totals[2] += machine.Created
		totals[3] += machine.Backtracks
	}
	stats = append(stats, fmt.Sprintf("total: solutions=%d inferences=%d choicepoints=%d backtracks=%d", totals[0], totals[1], totals[2], totals[3]), "== profile ==")
	indicators := []Indicator{}
	for p, profile := range profiles {
		if profile.Calls > 0 {
			indicators = append(indicators, p)
		}
	}
	sort.Slice(indicators, func(i, j int) bool {
		a, b := indicators[i], indicators[j]
		if profiles[a].Calls != profiles[b].Calls {
			return profiles[a].Calls > profiles[b].Calls
		}
		return indicatorText(a) < indicatorText(b)
	})
	for _, p := range indicators {
		line := fmt.Sprintf("%s calls=%d", indicatorText(p), profiles[p].Calls)
		if consultant.Database.Predicates[p] != nil {
			line += fmt.Sprintf(" tries=%d", profiles[p].Tries)
		}
		stats = append(stats, line)
	}
	if err := os.MkdirAll("output", 0755); err != nil {
		panic(err)
	}
	save("consult.txt", consultant.reportLines())
	save("listing.txt", listing(consultant.Database))
	save("answers.txt", answers)
	save("stats.txt", stats)
	if err := os.WriteFile("output/write_output.txt", []byte(writes.String()), 0644); err != nil {
		panic(err)
	}
}

package main

import "strings"

type BuiltinIssue struct{ Term *Term }

func predicateError(t *Term) { panic(BuiltinIssue{t}) }
func integerCheck(t *Term) int64 {
	t = dereference(t)
	if t.Kind == "variable" {
		predicateError(atom("instantiation_error"))
	}
	if t.Kind != "integer" {
		predicateError(errorTerm("type_error", atom("integer"), t))
	}
	return t.Integer
}
func atomCheck(t *Term) string {
	t = dereference(t)
	if t.Kind == "variable" {
		predicateError(atom("instantiation_error"))
	}
	if t.Kind != "atom" {
		predicateError(errorTerm("type_error", atom("atom"), t))
	}
	return t.Name
}
func properListCheck(t *Term) []*Term {
	elements, tail := listParts(t)
	if tail.Kind == "variable" {
		predicateError(atom("instantiation_error"))
	}
	if !isNil(tail) {
		predicateError(errorTerm("type_error", atom("list"), t))
	}
	return elements
}
func arithmeticValue(t *Term) int64 {
	t = dereference(t)
	if t.Kind == "variable" {
		predicateError(atom("instantiation_error"))
	}
	if t.Kind == "integer" {
		return t.Integer
	}
	p := indicator(t)
	valid := p.Arity == 2 && (p.Name == "+" || p.Name == "-" || p.Name == "*" || p.Name == "//" || p.Name == "mod" || p.Name == "rem" || p.Name == "min" || p.Name == "max") || p.Arity == 1 && (p.Name == "-" || p.Name == "abs")
	if !valid {
		predicateError(errorTerm("type_error", atom("evaluable"), indicatorTerm(p)))
	}
	a := arithmeticValue(t.Arguments[0])
	result := int64(0)
	if p.Arity == 1 {
		result = -a
		if p.Name == "abs" && a >= 0 {
			result = a
		}
	} else {
		b := arithmeticValue(t.Arguments[1])
		switch p.Name {
		case "+":
			result = a + b
		case "-":
			result = a - b
		case "*":
			result = a * b
		case "//", "mod", "rem":
			if b == 0 {
				predicateError(errorTerm("evaluation_error", atom("zero_divisor")))
			}
			q := a / b
			if p.Name == "//" {
				result = q
			} else {
				if p.Name == "mod" && a%b != 0 && (a < 0) != (b < 0) {
					q--
				}
				result = a - b*q
			}
		case "min":
			result = min(a, b)
		case "max":
			result = max(a, b)
		}
	}
	if result < -2147483648 || result > 2147483647 {
		predicateError(errorTerm("evaluation_error", atom("int_overflow")))
	}
	return result
}

var deterministicIndicators = map[Indicator]bool{
	{"true", 0}: true, {"fail", 0}: true, {"false", 0}: true, {"=", 2}: true, {"\\=", 2}: true, {"==", 2}: true, {"\\==", 2}: true,
	{"var", 1}: true, {"nonvar", 1}: true, {"atom", 1}: true, {"number", 1}: true, {"integer", 1}: true, {"atomic", 1}: true, {"compound", 1}: true, {"callable", 1}: true, {"is_list", 1}: true,
	{"is", 2}: true, {"=:=", 2}: true, {"=\\=", 2}: true, {"<", 2}: true, {">", 2}: true, {"=<", 2}: true, {">=", 2}: true,
	{"functor", 3}: true, {"arg", 3}: true, {"=..", 2}: true, {"copy_term", 2}: true, {"atom_length", 2}: true, {"atom_chars", 2}: true, {"write", 1}: true, {"writeq", 1}: true, {"nl", 0}: true,
}

func deterministic(goal *Term, bindings *Bindings, output *strings.Builder) bool {
	p := indicator(goal)
	args := goal.Arguments
	a := func(i int) *Term { return dereference(args[i]) }
	switch p.Name {
	case "true":
		return true
	case "fail", "false":
		return false
	case "=":
		return bindings.unify(args[0], args[1])
	case "\\=":
		mark := bindings.mark()
		success := bindings.unify(args[0], args[1])
		bindings.undo(mark)
		return !success
	case "==":
		return identical(args[0], args[1])
	case "\\==":
		return !identical(args[0], args[1])
	case "var":
		return a(0).Kind == "variable"
	case "nonvar":
		return a(0).Kind != "variable"
	case "atom":
		return a(0).Kind == "atom"
	case "number", "integer":
		return a(0).Kind == "integer"
	case "atomic":
		return a(0).Kind == "atom" || a(0).Kind == "integer"
	case "compound":
		return a(0).Kind == "compound"
	case "callable":
		return a(0).Kind == "atom" || a(0).Kind == "compound"
	case "is_list":
		_, tail := listParts(args[0])
		return isNil(tail)
	case "is":
		value := arithmeticValue(args[1])
		return bindings.unify(args[0], integer(value))
	case "=:=", "=\\=", "<", ">", "=<", ">=":
		x := arithmeticValue(args[0])
		y := arithmeticValue(args[1])
		switch p.Name {
		case "=:=":
			return x == y
		case "=\\=":
			return x != y
		case "<":
			return x < y
		case ">":
			return x > y
		case "=<":
			return x <= y
		case ">=":
			return x >= y
		}
	case "functor":
		t, n, arity := a(0), a(1), a(2)
		if t.Kind != "variable" {
			if t.Kind == "compound" {
				return bindings.unify(args[1], atom(t.Name)) && bindings.unify(args[2], integer(int64(len(t.Arguments))))
			}
			return bindings.unify(args[1], t) && bindings.unify(args[2], integer(0))
		}
		if n.Kind == "variable" || arity.Kind == "variable" {
			predicateError(atom("instantiation_error"))
		}
		if n.Kind == "compound" {
			predicateError(errorTerm("type_error", atom("atomic"), n))
		}
		if arity.Kind != "integer" {
			predicateError(errorTerm("type_error", atom("integer"), arity))
		}
		if arity.Integer < 0 {
			predicateError(errorTerm("domain_error", atom("not_less_than_zero"), arity))
		}
		if arity.Integer > 255 {
			predicateError(errorTerm("representation_error", atom("max_arity")))
		}
		if arity.Integer == 0 {
			return bindings.unify(args[0], n)
		}
		if n.Kind == "integer" {
			predicateError(errorTerm("type_error", atom("atom"), n))
		}
		values := []*Term{}
		for i := int64(0); i < arity.Integer; i++ {
			values = append(values, variable())
		}
		return bindings.unify(args[0], compound(n.Name, values...))
	case "arg":
		n, t := a(0), a(1)
		if n.Kind == "variable" || t.Kind == "variable" {
			predicateError(atom("instantiation_error"))
		}
		if n.Kind != "integer" {
			predicateError(errorTerm("type_error", atom("integer"), n))
		}
		if t.Kind != "compound" {
			predicateError(errorTerm("type_error", atom("compound"), t))
		}
		if n.Integer < 1 || n.Integer > int64(len(t.Arguments)) {
			return false
		}
		return bindings.unify(t.Arguments[int(n.Integer)-1], args[2])
	case "=..":
		t := a(0)
		if t.Kind == "compound" {
			values := append([]*Term{atom(t.Name)}, t.Arguments...)
			return bindings.unify(makeList(values, nil), args[1])
		}
		if t.Kind != "variable" {
			return bindings.unify(makeList([]*Term{t}, nil), args[1])
		}
		elements := properListCheck(args[1])
		if len(elements) == 0 {
			predicateError(errorTerm("domain_error", atom("non_empty_list"), atom("[]")))
		}
		head := dereference(elements[0])
		if head.Kind == "variable" {
			predicateError(atom("instantiation_error"))
		}
		if len(elements) == 1 {
			if head.Kind == "compound" {
				predicateError(errorTerm("type_error", atom("atomic"), head))
			}
			return bindings.unify(args[0], head)
		}
		if head.Kind != "atom" {
			predicateError(errorTerm("type_error", atom("atom"), head))
		}
		if len(elements)-1 > 255 {
			predicateError(errorTerm("representation_error", atom("max_arity")))
		}
		return bindings.unify(args[0], compound(head.Name, elements[1:]...))
	case "copy_term":
		return bindings.unify(copyTerm(args[0]), args[1])
	case "atom_length":
		name := atomCheck(args[0])
		n := a(1)
		if n.Kind != "variable" && n.Kind != "integer" {
			predicateError(errorTerm("type_error", atom("integer"), n))
		}
		return bindings.unify(integer(int64(len(name))), args[1])
	case "atom_chars":
		t := a(0)
		if t.Kind != "variable" {
			name := atomCheck(t)
			values := []*Term{}
			for i := 0; i < len(name); i++ {
				values = append(values, atom(name[i:i+1]))
			}
			return bindings.unify(args[1], makeList(values, nil))
		}
		elements := properListCheck(args[1])
		var name strings.Builder
		for _, element := range elements {
			element = dereference(element)
			if element.Kind == "variable" {
				predicateError(atom("instantiation_error"))
			}
			if element.Kind != "atom" || len(element.Name) != 1 {
				predicateError(errorTerm("type_error", atom("character"), element))
			}
			name.WriteString(element.Name)
		}
		return bindings.unify(args[0], atom(name.String()))
	case "write", "writeq":
		writer := newWriter(p.Name == "writeq")
		output.WriteString(writer.write(args[0], 1200, false))
		return true
	case "nl":
		output.WriteByte('\n')
		return true
	}
	panic("unknown deterministic predicate")
}

package main

import (
	"fmt"
	"strings"
)

type Position struct{ Line, Column int }
type Token struct {
	Kind, Name, Spelling, Message string
	Integer                       int64
	Position                      Position
	Whitespace                    bool
}

func lower(c byte) bool        { return c >= 'a' && c <= 'z' }
func upper(c byte) bool        { return c >= 'A' && c <= 'Z' }
func digit(c byte) bool        { return c >= '0' && c <= '9' }
func alphanumeric(c byte) bool { return lower(c) || upper(c) || digit(c) || c == '_' }
func symbol(c byte) bool       { return strings.ContainsRune("+-*/\\^<>=~:.?@#&$", rune(c)) }
func lex(source string, startColumn int) []Token {
	tokens := []Token{}
	i, line, column := 0, 1, startColumn
	space := true
	for i < len(source) {
		c := source[i]
		if c == ' ' || c == '\n' {
			space = true
			i++
			if c == '\n' {
				line++
				column = 1
			} else {
				column++
			}
			continue
		}
		if c == '%' {
			space = true
			for i < len(source) && source[i] != '\n' {
				i++
				column++
			}
			continue
		}
		start := i
		t := Token{Position: Position{line, column}, Whitespace: space}
		space = false
		switch {
		case digit(c):
			t.Kind = "integer"
			n := int64(0)
			tooLarge := false
			for i < len(source) && digit(source[i]) {
				if n > 214748364 || n == 214748364 && source[i] > '7' {
					tooLarge = true
				}
				if !tooLarge {
					n = n*10 + int64(source[i]-'0')
				}
				i++
				column++
			}
			t.Integer = n
			if tooLarge {
				t.Kind = "invalid"
				t.Message = "integer too large"
			}
		case lower(c) || upper(c) || c == '_':
			t.Kind = "name"
			if !lower(c) {
				t.Kind = "variable"
			}
			for i < len(source) && alphanumeric(source[i]) {
				i++
				column++
			}
			t.Name = source[start:i]
		case symbol(c):
			for i < len(source) && symbol(source[i]) {
				i++
				column++
			}
			t.Name = source[start:i]
			t.Kind = "name"
			if t.Name == "." && (i == len(source) || source[i] == ' ' || source[i] == '\n' || source[i] == '%') {
				t.Kind = "end"
			}
		case c == '!' || c == ';':
			t.Kind = "name"
			t.Name = string(c)
			i++
			column++
		case strings.ContainsRune(",|()[]", rune(c)):
			t.Kind = "punctuation"
			t.Name = string(c)
			i++
			column++
		case c == '\'':
			t.Kind = "quoted"
			i++
			column++
			var name strings.Builder
			incorrect := false
			closed := false
			for i < len(source) && source[i] != '\n' {
				c = source[i]
				if c == '\'' {
					if i+1 < len(source) && source[i+1] == '\'' {
						name.WriteByte('\'')
						i += 2
						column += 2
						continue
					}
					i++
					column++
					closed = true
					break
				}
				if c == '\\' {
					if i+1 == len(source) || source[i+1] == '\n' {
						i++
						column++
						continue
					}
					next := source[i+1]
					switch next {
					case 'n':
						name.WriteByte('\n')
					case 't':
						name.WriteByte('\t')
					case '\\', '\'':
						name.WriteByte(next)
					default:
						incorrect = true
					}
					i += 2
					column += 2
					continue
				}
				name.WriteByte(c)
				i++
				column++
			}
			if !closed {
				t.Kind = "invalid"
				t.Message = "unterminated quoted atom"
			} else if incorrect {
				t.Kind = "invalid"
				t.Message = "undefined escape sequence"
			} else {
				t.Name = name.String()
			}
		default:
			t.Kind = "invalid"
			t.Message = fmt.Sprintf("illegal character '%c'", c)
			i++
			column++
		}
		t.Spelling = source[start:i]
		tokens = append(tokens, t)
	}
	return append(tokens, Token{Kind: "eof", Position: Position{line, column}, Whitespace: space})
}

type Operator struct{ Priority, Left, Right int }

var infixOperators = map[string]Operator{
	":-": {1200, 1199, 1199}, ";": {1100, 1099, 1100}, "->": {1050, 1049, 1050}, ",": {1000, 999, 1000},
	"=": {700, 699, 699}, "\\=": {700, 699, 699}, "==": {700, 699, 699}, "\\==": {700, 699, 699}, "is": {700, 699, 699}, "=:=": {700, 699, 699}, "=\\=": {700, 699, 699}, "<": {700, 699, 699}, ">": {700, 699, 699}, "=<": {700, 699, 699}, ">=": {700, 699, 699}, "=..": {700, 699, 699},
	"+": {500, 500, 499}, "-": {500, 500, 499}, "*": {400, 400, 399}, "/": {400, 400, 399}, "//": {400, 400, 399}, "mod": {400, 400, 399}, "rem": {400, 400, 399},
}
var prefixOperators = map[string]int{"\\+": 900, "-": 200}

type SyntaxIssue struct {
	Token   Token
	Index   int
	Message string
}
type Reader struct {
	Tokens []Token
	Index  int
	Named  map[string]*Term
	Counts map[string]int
	Order  []string
}

func (r *Reader) peek() Token { return r.Tokens[r.Index] }
func (r *Reader) take() Token {
	token := r.peek()
	if token.Kind != "eof" {
		r.Index++
	}
	return token
}
func (r *Reader) fail(token Token, index int, message string) {
	if message == "" {
		switch token.Kind {
		case "invalid":
			message = token.Message
		case "eof":
			message = "unexpected end of file"
		case "end":
			message = "unexpected end of clause"
		default:
			_, operator := infixOperators[token.Name]
			if token.Kind == "name" && operator {
				message = "operator priority clash"
			} else {
				message = "unexpected \"" + token.Spelling + "\""
			}
		}
	}
	panic(SyntaxIssue{token, index, message})
}
func (r *Reader) expect(name string) {
	index := r.Index
	token := r.take()
	if token.Kind != "punctuation" || token.Name != name {
		r.fail(token, index, "")
	}
}
func (r *Reader) canStart(t Token) bool {
	if t.Kind == "integer" || t.Kind == "variable" || t.Kind == "quoted" {
		return true
	}
	if t.Kind == "punctuation" && (t.Name == "(" || t.Name == "[") {
		return true
	}
	if t.Kind == "name" {
		_, infix := infixOperators[t.Name]
		_, prefix := prefixOperators[t.Name]
		return !infix || prefix
	}
	return false
}
func (r *Reader) term(limit int) (*Term, int) {
	left, priority := r.primary(limit)
	for {
		next := r.peek()
		op, ok := infixOperators[next.Name]
		if !ok || next.Kind != "name" && (next.Kind != "punctuation" || next.Name != ",") || op.Priority > limit || priority > op.Left {
			return left, priority
		}
		r.take()
		right, _ := r.term(op.Right)
		left = compound(next.Name, left, right)
		priority = op.Priority
	}
}
func (r *Reader) primary(limit int) (*Term, int) {
	index := r.Index
	t := r.take()
	switch t.Kind {
	case "integer":
		return integer(t.Integer), 0
	case "variable":
		r.Counts[t.Name]++
		if r.Counts[t.Name] == 1 {
			r.Order = append(r.Order, t.Name)
		}
		if t.Name == "_" {
			return variable(), 0
		}
		if previous := r.Named[t.Name]; previous != nil {
			return previous, 0
		}
		v := variable()
		r.Named[t.Name] = v
		return v, 0
	case "punctuation":
		if t.Name == "(" {
			value, _ := r.term(1200)
			r.expect(")")
			return value, 0
		}
		if t.Name == "[" {
			if r.peek().Kind == "punctuation" && r.peek().Name == "]" {
				r.take()
				return atom("[]"), 0
			}
			value, _ := r.term(999)
			elements := []*Term{value}
			for r.peek().Kind == "punctuation" && r.peek().Name == "," {
				r.take()
				value, _ = r.term(999)
				elements = append(elements, value)
			}
			tail := atom("[]")
			if r.peek().Kind == "punctuation" && r.peek().Name == "|" {
				r.take()
				tail, _ = r.term(999)
			}
			r.expect("]")
			return makeList(elements, tail), 0
		}
	case "name", "quoted":
		if next := r.peek(); next.Kind == "punctuation" && next.Name == "(" && !next.Whitespace {
			r.take()
			value, _ := r.term(999)
			args := []*Term{value}
			for r.peek().Kind == "punctuation" && r.peek().Name == "," {
				r.take()
				value, _ = r.term(999)
				args = append(args, value)
			}
			r.expect(")")
			return compound(t.Name, args...), 0
		}
		if t.Kind == "name" && t.Name == "-" && r.peek().Kind == "integer" && !r.peek().Whitespace {
			return integer(-r.take().Integer), 0
		}
		if priority, ok := prefixOperators[t.Name]; t.Kind == "name" && ok && r.canStart(r.peek()) {
			if priority > limit {
				r.fail(t, index, "operator priority clash")
			}
			value, _ := r.term(priority)
			return compound(t.Name, value), priority
		}
		return atom(t.Name), 0
	}
	r.fail(t, index, "")
	return nil, 0
}
func (r *Reader) clause(query bool) *Term {
	r.Named = map[string]*Term{}
	r.Counts = map[string]int{}
	r.Order = nil
	term, _ := r.term(1200)
	index := r.Index
	t := r.take()
	if t.Kind != "end" {
		r.fail(t, index, "")
	}
	if query && r.peek().Kind != "eof" {
		r.fail(r.peek(), r.Index, "")
	}
	return term
}
func readClause(r *Reader, query bool) (term *Term, issue *SyntaxIssue) {
	defer func() {
		if failure := recover(); failure != nil {
			if error, ok := failure.(SyntaxIssue); ok {
				issue = &error
			} else {
				panic(failure)
			}
		}
	}()
	return r.clause(query), nil
}

package main

type Term struct {
	Kind, Name string
	Integer    int64
	Arguments  []*Term
	Binding    *Term
}

func atom(name string) *Term { return &Term{Kind: "atom", Name: name} }
func integer(n int64) *Term  { return &Term{Kind: "integer", Integer: n} }
func variable() *Term        { return &Term{Kind: "variable"} }
func compound(name string, args ...*Term) *Term {
	return &Term{Kind: "compound", Name: name, Arguments: args}
}
func dereference(t *Term) *Term {
	for t.Kind == "variable" && t.Binding != nil {
		t = t.Binding
	}
	return t
}
func isCompound(t *Term, name string, arity int) bool {
	t = dereference(t)
	return t.Kind == "compound" && t.Name == name && len(t.Arguments) == arity
}
func isNil(t *Term) bool {
	t = dereference(t)
	return t.Kind == "atom" && t.Name == "[]"
}
func makeList(elements []*Term, tail *Term) *Term {
	if tail == nil {
		tail = atom("[]")
	}
	for i := len(elements) - 1; i >= 0; i-- {
		tail = compound(".", elements[i], tail)
	}
	return tail
}
func listParts(t *Term) ([]*Term, *Term) {
	elements := []*Term{}
	t = dereference(t)
	for isCompound(t, ".", 2) {
		elements = append(elements, t.Arguments[0])
		t = dereference(t.Arguments[1])
	}
	return elements, t
}

type Copier struct{ Variables map[*Term]*Term }

func newCopier() *Copier { return &Copier{Variables: map[*Term]*Term{}} }
func (c *Copier) copy(t *Term) *Term {
	t = dereference(t)
	if t.Kind == "variable" {
		if v := c.Variables[t]; v != nil {
			return v
		}
		v := variable()
		c.Variables[t] = v
		return v
	}
	if t.Kind != "compound" {
		return t
	}
	args := []*Term{}
	for _, arg := range t.Arguments {
		args = append(args, c.copy(arg))
	}
	return compound(t.Name, args...)
}
func copyTerm(t *Term) *Term { return newCopier().copy(t) }
func termVariables(t *Term) []*Term {
	out := []*Term{}
	var walk func(*Term)
	walk = func(t *Term) {
		t = dereference(t)
		if t.Kind == "variable" {
			out = append(out, t)
		} else if t.Kind == "compound" {
			for _, arg := range t.Arguments {
				walk(arg)
			}
		}
	}
	walk(t)
	return out
}

type Indicator struct {
	Name  string
	Arity int
}

func indicator(t *Term) Indicator {
	t = dereference(t)
	if t.Kind == "atom" {
		return Indicator{t.Name, 0}
	}
	return Indicator{t.Name, len(t.Arguments)}
}
func indicatorTerm(p Indicator) *Term { return compound("/", atom(p.Name), integer(int64(p.Arity))) }
func errorTerm(kind string, args ...*Term) *Term {
	if len(args) == 0 {
		return atom(kind)
	}
	return compound(kind, args...)
}
func errorBall(error *Term, p Indicator) *Term { return compound("error", error, indicatorTerm(p)) }

package main

type Bindings struct{ Trail []*Term }

func (b *Bindings) mark() int { return len(b.Trail) }
func (b *Bindings) undo(mark int) {
	for len(b.Trail) > mark {
		last := b.Trail[len(b.Trail)-1]
		last.Binding = nil
		b.Trail = b.Trail[:len(b.Trail)-1]
	}
}
func (b *Bindings) bind(v, t *Term) {
	v.Binding = t
	b.Trail = append(b.Trail, v)
}
func (b *Bindings) unify(a, c *Term) bool {
	pairs := [][2]*Term{{a, c}}
	for len(pairs) > 0 {
		pair := pairs[len(pairs)-1]
		pairs = pairs[:len(pairs)-1]
		x, y := dereference(pair[0]), dereference(pair[1])
		if x == y {
			continue
		}
		if x.Kind == "variable" {
			b.bind(x, y)
			continue
		}
		if y.Kind == "variable" {
			b.bind(y, x)
			continue
		}
		if x.Kind != y.Kind {
			return false
		}
		switch x.Kind {
		case "integer":
			if x.Integer != y.Integer {
				return false
			}
		case "atom":
			if x.Name != y.Name {
				return false
			}
		case "compound":
			if x.Name != y.Name || len(x.Arguments) != len(y.Arguments) {
				return false
			}
			for i := len(x.Arguments) - 1; i >= 0; i-- {
				pairs = append(pairs, [2]*Term{x.Arguments[i], y.Arguments[i]})
			}
		}
	}
	return true
}
func identical(a, b *Term) bool {
	pairs := [][2]*Term{{a, b}}
	for len(pairs) > 0 {
		pair := pairs[len(pairs)-1]
		pairs = pairs[:len(pairs)-1]
		x, y := dereference(pair[0]), dereference(pair[1])
		if x == y {
			continue
		}
		if x.Kind != y.Kind {
			return false
		}
		switch x.Kind {
		case "variable":
			return false
		case "integer":
			if x.Integer != y.Integer {
				return false
			}
		case "atom":
			if x.Name != y.Name {
				return false
			}
		case "compound":
			if x.Name != y.Name || len(x.Arguments) != len(y.Arguments) {
				return false
			}
			for i := len(x.Arguments) - 1; i >= 0; i-- {
				pairs = append(pairs, [2]*Term{x.Arguments[i], y.Arguments[i]})
			}
		}
	}
	return true
}
